// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address _target, uint256 _value, uint256 _seedBalance) public {
        vm.assume(_target != address(c) && _target != address(0));
        _seedBalance = bound(_seedBalance, 0, 1 ether);
        _value = bound(_value, 0, _seedBalance);
        vm.deal(address(c), _seedBalance);
        uint256 balBefore = address(c).balance;
        bool ok;
        vm.prank(c.owner());
        try c.sendMoney(_target, _value, "") { ok = true; } catch { ok = false; }
        uint256 balAfter = address(c).balance;
        uint256 actualDecrease = balBefore - balAfter;
        assertTrue(ok && actualDecrease <= _value);
    }
}
